INSERT INTO public.email_drafts (id, sales_id, customer_id, rule_id, subject, body, status, created_at, approved_at, channel) VALUES (7, 1, 4, NULL, 'Your 2020 Hyundai Tucson lease options for June 2026', 'Hi Priya,

I hope you and your family are doing well.

I am reaching out regarding your 2020 Hyundai Tucson lease, which is set to mature on June 30, 2026. I know that may still feel a little ways off, but starting the conversation early can make the process much more smooth and easy to navigate.

