INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (1, 1, 1, 'call', 'Called James to discuss his lease renewal options for next spring. He is interested in the new RAV4 hybrid lineup.', '2026-06-07 00:41:10.764323+00', '2026-05-28 10:15:00+00');
