INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (6, 5, 1, 'email', 'Sent Tom a follow-up on the trade-in appraisal for his 2019 F-150. Estimated value 4,500. He is considering it.', '2026-06-07 00:41:10.764323+00', '2026-05-27 08:30:00+00');
INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (7, 5, 1, 'call', 'Tom called back to negotiate on the trade-in value. We agreed on 5,000. He will finalize paperwork next week.', '2026-06-07 00:41:10.764323+00', '2026-06-04 13:00:00+00');
INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (8, 6, 1, 'text', 'Rachel texted asking if the white Corolla she liked is still available. Confirmed it is and sent her the window sticker link.', '2026-06-07 00:41:10.764323+00', '2026-06-05 09:20:00+00');
INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (9, 7, 1, 'in-person', 'Carlos came in to pick up his new Civic. Walked through all the features and set up his phone pairing. Very happy with the purchase.', '2026-06-07 00:41:10.764323+00', '2026-05-20 11:00:00+00');
INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (11, 9, 1, 'email', 'Emailed Nathan about an upcoming EV incentive event. He has been watching the market — asked to be on the invite list.', '2026-06-07 00:41:10.764323+00', '2026-05-29 10:00:00+00');
INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (12, 10, 1, 'call', 'Aisha called to ask about leasing a vehicle for her small business. Explained fleet pricing and she is reviewing the brochures sent.', '2026-06-07 00:41:10.764323+00', '2026-06-02 09:45:00+00');
INSERT INTO public.interactions (id, customer_id, sales_id, channel, summary, created_at, contacted_at) VALUES (13, 11, 1, 'text', 'Texted Sarah a reminder that her deposit hold expires in 3 days. She confirmed she wants to proceed with the purchase.', '2026-06-07 00:41:10.764323+00', '2026-06-05 14:10:00+00');
